def create_initial_state(question):
    """
    Create the initial state for a research task.
    """

    # Store all information needed by our research agent
    state={
        # Original question asked by the user
        "question": question,

        # Research tasks generated by the planner
        "plan":[],

        # Raw Information returned from web/paper searches
        "search_results":[],


        # SEARCH RESULT = raw information from a source.

        #EVIDENCE = useful information extracted from that source.
        

        # Useful facts & info extracted from search results
        "evidence":[],
        "evidence_origins":[],

        # evaluate the search sources
        "source_evaluations": [],

        # Information that is still missing requires further search
        "gaps":[],

        # Verifies whether important claims are supported by evidence.
        "verified_claims":[],
        "claim_verifications":[],
        
        # creates structured source records with unique IDs (e.g., SRC-001)
        "sources": [],

        # Maps verified claims to their respective source IDs
        "citations": [],

        # Closest retrieved source matches for extracted evidence
        "evidence_matches": [],

        # Non-fatal claim verification error, if verification could not complete
        "verification_error": "",

        # Final generated research report text
        "report":[],

        # Keeps track of which research task we are working on
        "current_task": 0,

        # Counts how many research cycles the agent has performed
        "iteration": 0
    }

    # Return the initial state
    return state

# Simple test when this file is run directly
if __name__ == "__main__":

    # Example research question
    question = "What is Retrieval-Augmented Generation (RAG)?"

    # Create the initial state
    state = create_initial_state(question)

    # Display the state
    print("\n========== INITIAL STATE ==========\n")
    print(state)